<?php require_once 'db.php';require_once 'functions.php';$u=login_required($pdo);$msg='';$err='';if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$a=$_POST['action']??'';if($a==='add'){ $r=trim($_POST['recipient_name']??'');$ph=trim($_POST['phone']??'');$ad=trim($_POST['address']??'');$city=trim($_POST['city']??'');$prov=trim($_POST['province']??'');$zip=trim($_POST['postal_code']??'');if($r===''||$ph===''||$ad===''||$city===''||$prov===''||$zip==='')$err='Field alamat utama wajib diisi.';else{$s=$pdo->prepare('INSERT INTO addresses(user_id,label,recipient_name,phone,address,village,district,city,province,postal_code) VALUES(?,?,?,?,?,?,?,?,?,?)');$s->execute([$u['id'],trim($_POST['label']??'')?:null,$r,$ph,$ad,trim($_POST['village']??'')?:null,trim($_POST['district']??'')?:null,$city,$prov,$zip]);$id=(int)$pdo->lastInsertId();if((int)$pdo->query('SELECT COUNT(*) FROM addresses WHERE user_id='.(int)$u['id'])->fetchColumn()===1){$pdo->prepare('UPDATE addresses SET is_default=1 WHERE id=?')->execute([$id]);}$msg='Alamat tersimpan.';}}if($a==='default'){$id=(int)$_POST['id'];$pdo->beginTransaction();$pdo->prepare('UPDATE addresses SET is_default=0 WHERE user_id=?')->execute([$u['id']]);$pdo->prepare('UPDATE addresses SET is_default=1 WHERE id=? AND user_id=?')->execute([$id,$u['id']]);$pdo->commit();$msg='Default address diperbarui.';}if($a==='delete'){$id=(int)$_POST['id'];$pdo->prepare('DELETE FROM addresses WHERE id=? AND user_id=? AND is_default=0')->execute([$id,$u['id']]);$msg='Alamat dihapus bila bukan default.';}}
$s=$pdo->prepare('SELECT * FROM addresses WHERE user_id=? ORDER BY is_default DESC,id DESC');$s->execute([$u['id']]);$rows=$s->fetchAll();?><?php $pageTitle='Alamat pengiriman'; include 'layout_top.php'; ?><h1>My Addresses</h1><?php if($msg):?><div class="alert success"><?=e($msg)?></div><?php endif;?><?php if($err):?><div class="alert error"><?=e($err)?></div><?php endif;?><div class="two"><div class="card"><h2>Tambah Alamat</h2><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf())?>"><input type="hidden" name="action" value="add"><label>Label</label><input name="label" placeholder="Rumah/Kos/Kantor"><label>Penerima</label><input name="recipient_name" required><label>Telepon</label><input name="phone" required><label>Alamat</label><textarea name="address" required></textarea><div class="row"><div><label>Kelurahan</label><input name="village"></div><div><label>Kecamatan</label><input name="district"></div></div><div class="row"><div><label>Kota/Kab.</label><input name="city" required></div><div><label>Provinsi</label><input name="province" required></div></div><label>Kode Pos</label><input name="postal_code" required><button class="btn primary">Simpan</button></form></div><div class="card"><h2>Alamat Tersimpan</h2><?php foreach($rows as $r):?><div class="address"><b><?=e($r['label']?:'Address')?> <?php if($r['is_default']):?><span class="badge">Default</span><?php endif;?></b><p><?=e($r['recipient_name'])?> · <?=e($r['phone'])?><br><?=nl2br(e($r['address']))?><br><?=e($r['city'])?>, <?=e($r['province'])?> <?=e($r['postal_code'])?></p><div class="actions"><?php if(!$r['is_default']):?><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf())?>"><input type="hidden" name="action" value="default"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="btn-sm primary">Set Default</button></form><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf())?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="btn-sm danger">Delete</button></form><?php endif;?></div></div><?php endforeach;?><?php if(!$rows):?><p class="muted">Belum ada alamat.</p><?php endif;?></div></div><?php include 'layout_bottom.php'; ?>
